    symbols=[h('module','Module','__init__ add get bundle_ports','construct','模块容器及命名信号/实例入口。'),h('module','module',None,'construct','声明式模块装饰器。'),h('signal','Signal',[],'connect','内部信号状态，width/name/visibility/direction字段。','@datatype生成构造；Signal(name=...,width=...)，保留字段契约而不伪造源__init__。'),h('external_module','ExternalModule','__call__','construct','显式模型接口，调用设置参数，端口/模型类型为状态。','@datatype生成构造，字段name/port_list/paramtype/domain/spicetype见原始类源码；运行固定NMOS外部模型。'),h('external_module','ExternalModuleCall',[],'connect','参数化模型与连接调用分离，避免把参数当网络。','由ExternalModule.__call__返回；@calls_instantiate动态附加__call__(**kwargs)返回Instance并连接，动态方法不伪造进AST候选。'),h('instance','Instance','__init__','connect','实例容器和of/conns/name状态；显式构造转发真实基类参数。'),h('instance','InstanceArray','__init__','connect','同一单元阵列与广播连接。'),h('concat','Concat','__init__','connect','连接总线片段，位宽作为派生状态。'),h('bundle','Bundle','__init__ add get','connect','成组信号接口，保留构造与属性增查。'),h('bundle','BundleInstance','__init__','connect','实例化成组接口。'),h('bundle','AnonymousBundle','__init__ add get','connect','按名绑定已有信号为匿名接口。'),h('props','Properties','set get remove','inspect','附加结构注释和设计约束状态。'),h('generator','Generator','__call__','generate','参数化模块调用与缓存入口。','由generator装饰器构造，func/paramtype/enable_cache为@datatype字段。'),h('generator','GeneratorCache','reset','generate','参数化生成器缓存重置，用于独立任务隔离。','零参数构造沿用object.__init__，源类无显式构造。'),h('prefix','Prefixed','new scale','parameter','物理量前缀构造和缩放，避免米/微米混淆。','由new或to_prefixed返回，@datatype字段number/prefix。'),h('prefix','Prefix','from_exp closest','parameter','十进制单位前缀选择；枚举值不作为普通构造。','枚举成员或from_exp/closest返回。'),v('netlist.fmt','NetlistFormat','get to_proto from_proto','export','网表格式解析和Schema枚举互转；不直接暴露内部writer。','Enum成员或get返回。'),v('spicetype','SpiceType','to_schema from_schema','export','MOS/SUBCKT等外部元件语义与Schema对应。','使用SpiceType.MOS等枚举值，不虚构构造。')]
